for(const [id,title] of [[224,'Parshas Vayakhel Pekudei'],[222,'Parshas Tazria & Metzorah'],[100003,'Parshas Achrei Mos-Kedoshim'],[223,'Parshas Behar Bechukosai'],[100082,'Parshas Nitzavim-Vayeilech'],[37,'Haggadah Shel Pesach'],[37,'Hagadah'],[36,'Megillas Esther'],[36,'Mishloach Manos'],[29,'Arba Minim'],[32,'שמיני עצרת'],[229,'Parshas Shekalim'],[232,'Parshas Zachor'],[235,'Parshas Parah'],[236,'Parshas HaChodesh']])test('independent concept/combination '+title,()=>expectId(title,id,{calendar:forbidden}));
