// Independent unseen typo cases; expected semantic labels fixed by human-readable
// transpositions, never by the fuzzy scorer or historical lookup.
let heuristicAccepted=0,heuristicWrong=0,heuristicRefused=0;
const heuristicHoldout=[[62,'Mishpatmi'],[56,'Vayehci'],[77,'Bechuksoai'],[88,'Devarmi'],[95,'Nitzavmi'],[52,'Vayihslach'],[68,'Vaykira'],[72,'Metzroa'],[78,'Bamdibar'],[64,'Tetzavhe'],[74,'Kedoshmi'],[55,'Vayigahs'],[85,'Pinchsa'],[60,'Beshalcah']];
for(const [id,typo] of heuristicHoldout){
 const title='Parshas '+typo+' — independent holdout topic';
 test('independent unseen fuzzy '+typo,()=>{
  assert.equal(Object.hasOwn(production.api.verified,api.normalizeTitle(title)),false);
  const target=api.taxonomy.find(t=>t.subCategoryId===id);
  const result=api.classifyTitle({title,publicationDate:'2026-02-09'},{calendar:fixedCalendar([parsha(target.subCategoryName,'2026-02-14')])});
  if(result.ok){heuristicAccepted++;if(result.classification.subCategoryId!==id)heuristicWrong++;assert.equal(result.classification.subCategoryId,id);}
  else heuristicRefused++;
 });
 if(typo==='Vaykira')test('ambiguous Vaykira still needs calendar',()=>expectFailure(title));
 else test('unique unseen fuzzy works offline '+typo,()=>expectId(title,id,{calendar:forbidden}));
}
