for(const [title,id] of HISTORICAL)test('historical '+title,()=>{const r=production.api.classifyTitle({title},{calendar:forbidden});assert.equal(r.ok,true,title+': '+r.reason);assert.equal(r.classification.subCategoryId,id);assert.equal(r.reason,'Verified historical lookup');const rule=api.deterministicClassification(title);assert.equal(rule.ok,true,title+': '+rule.reason);assert.equal(rule.classification.subCategoryId,id);const expected=api.taxonomy.find(t=>t.subCategoryId===id);same(r.classification,JSON.parse(JSON.stringify(expected)));});
let holdoutAccepted=0,holdoutRefused=0,holdoutWrong=0;
for(const [title,id] of HOLDOUT)test('holdout '+title,()=>{assert.equal(Object.hasOwn(production.api.verified,title),false);const r=api.classifyTitle({title},{calendar:forbidden});if(r.ok){holdoutAccepted++;if(r.classification.subCategoryId!==id)holdoutWrong++;assert.equal(r.classification.subCategoryId,id);}else holdoutRefused++;});
// Every quarantine entry must fail without sufficient context, never silently return
// an existing unverified label. The administrator-approved pair needs a calendar.
for(const title of Object.keys(production.api.unverified))test('quarantine '+title,()=>{
 const result=production.api.classifyTitle({title});
 const direct=api.deterministicClassification(title);
 const exact=direct.ok&&api.entries.some(e=>e.taxon.subCategoryId===direct.classification.subCategoryId&&e.aliases.includes(title));
 if(production.api.unverified[title]==='Historical subtopic conflict; manual classification required'&&exact){
  assert.equal(result.ok,true);assert.equal(result.classification.subCategoryId,direct.classification.subCategoryId);
  assert.equal(result.reason,'Exact name overrides conflicting harvested labels');
 }else assert.equal(result.ok,false);
});
test('lookup and quarantine are disjoint',()=>{for(const title of Object.keys(production.api.verified))assert.equal(Object.hasOwn(production.api.unverified,title),false);});
test('holdout near-duplicate clusters never contain differing labels',()=>{const groups=new Map();for(const [,id,key] of HOLDOUT){if(groups.has(key))assert.equal(groups.get(key),id);else groups.set(key,id);}});
test('every historical fixture is unique',()=>assert.equal(new Set(HISTORICAL.map(([title])=>title)).size,HISTORICAL.length));
test('heuristic generalization resolves a close competitor',()=>{
 // Vayehci is one transposition from Vayechi; weaker two-edit suggestions do not
 // force a calendar lookup. This title is absent from all lookups.
 expectId('Parshas Vayehci — never encountered',56,{calendar:fixedCalendar([parsha('Vayechi','2026-01-03')])},{publicationDate:'2025-12-29'});
});
